/**
 * DeliverableCard — Phase 13.3E.5
 *
 * Displays a deliverable with full metadata: report name, audience, purpose,
 * status, current version, source valuation version, last generated,
 * generated by, review status, client-safe status, shared status, shared/
 * revoked dates, data freshness, stale warning, missing sections, and
 * permission-aware action buttons (Preview, Generate, Regenerate, Download,
 * Share, Revoke).
 */
import React from 'react';
import { FileText, Eye, Share2, RotateCcw, AlertTriangle, Clock, ShieldCheck, Lock } from 'lucide-react';
import { DELIVERABLE_STATUSES } from '@/lib/valuation/deliverablesEngine';

function StatusBadge({ status }) {
  const meta = DELIVERABLE_STATUSES[status] || DELIVERABLE_STATUSES.not_started;
  return (
    <span
      className="text-[9px] font-semibold uppercase tracking-wider px-1.5 py-0.5 rounded"
      style={{ color: meta.color, background: `${meta.color}15` }}
    >
      {meta.label}
    </span>
  );
}

export default function DeliverableCard({ deliverable, canPublish, onPreview, onGenerate, onShare, onRevoke }) {
  const Icon = FileText; // Icon mapping handled by audience
  const isClientSafe = deliverable.client_safe;
  const canGenerate = deliverable.can_generate && canPublish;
  const canShare = deliverable.can_share && canPublish;
  const canRevoke = deliverable.can_revoke && canPublish;
  const canPreview = deliverable.can_preview;

  return (
    <div
      className="rounded-xl p-3.5 flex flex-col"
      style={{ background: 'rgba(255,255,255,0.015)', border: '1px solid rgba(255,255,255,0.05)' }}
    >
      {/* Header */}
      <div className="flex items-start justify-between gap-2">
        <div className="min-w-0 flex-1">
          <div className="flex items-center gap-2">
            <p className="text-xs font-semibold text-foreground leading-tight">{deliverable.label}</p>
          </div>
          <p className="text-[10px] text-muted-foreground mt-1">{deliverable.purpose}</p>
        </div>
        <StatusBadge status={deliverable.status} />
      </div>

      {/* Audience + Client-safe badge */}
      <div className="flex items-center gap-2 mt-2.5">
        <span className="text-[10px] text-muted-foreground">Audience: {deliverable.audience}</span>
        {isClientSafe ? (
          <span className="flex items-center gap-1 text-[9px] text-accent">
            <ShieldCheck className="w-3 h-3" />
            Client-Safe
          </span>
        ) : (
          <span className="flex items-center gap-1 text-[9px] text-muted-foreground">
            <Lock className="w-3 h-3" />
            Internal Only
          </span>
        )}
      </div>

      {/* Metadata grid */}
      <div className="grid grid-cols-2 gap-1.5 mt-2.5 text-[10px]">
        <div className="flex items-center gap-1 text-muted-foreground">
          <span>Version:</span>
          <span className="text-foreground">{deliverable.current_version || '—'}</span>
        </div>
        <div className="flex items-center gap-1 text-muted-foreground">
          <span>Review:</span>
          <span className="text-foreground">{deliverable.review_status || '—'}</span>
        </div>
        {deliverable.last_generated && (
          <div className="flex items-center gap-1 text-muted-foreground">
            <Clock className="w-2.5 h-2.5" />
            <span>{new Date(deliverable.last_generated).toLocaleDateString()}</span>
          </div>
        )}
        {deliverable.generated_by && (
          <div className="flex items-center gap-1 text-muted-foreground">
            <span>By:</span>
            <span className="text-foreground truncate">{deliverable.generated_by}</span>
          </div>
        )}
      </div>

      {/* Stale warning */}
      {deliverable.stale_warning && (
        <div className="flex items-center gap-1.5 mt-2 text-[10px] text-destructive">
          <AlertTriangle className="w-3 h-3" />
          Source data has changed — regenerate to update.
        </div>
      )}

      {/* Shared status */}
      {deliverable.shared_status === 'shared' && (
        <div className="flex items-center gap-1.5 mt-2 text-[10px] text-accent">
          <Share2 className="w-3 h-3" />
          Shared with client {deliverable.shared_date ? `· ${new Date(deliverable.shared_date).toLocaleDateString()}` : ''}
        </div>
      )}
      {deliverable.shared_status === 'revoked' && (
        <div className="flex items-center gap-1.5 mt-2 text-[10px] text-destructive">
          <RotateCcw className="w-3 h-3" />
          Access revoked {deliverable.revoked_date ? `· ${new Date(deliverable.revoked_date).toLocaleDateString()}` : ''}
        </div>
      )}

      {/* Missing sections */}
      {deliverable.missing_sections?.length > 0 && (
        <div className="mt-2 text-[10px] text-muted-foreground">
          Missing: {deliverable.missing_sections.join(', ')}
        </div>
      )}

      {/* Actions */}
      <div className="flex items-center gap-1.5 mt-3 pt-2.5 border-t border-border/30 flex-wrap">
        {canPreview && (
          <button
            onClick={() => onPreview?.(deliverable)}
            className="flex items-center gap-1 text-[10px] text-primary hover:underline"
          >
            <Eye className="w-3 h-3" />
            Preview
          </button>
        )}
        {canGenerate && (
          <button
            onClick={() => onGenerate?.(deliverable)}
            className="flex items-center gap-1 text-[10px] text-primary hover:underline"
          >
            <FileText className="w-3 h-3" />
            {deliverable.status === 'generated' || deliverable.status === 'shared' ? 'Regenerate' : 'Generate'}
          </button>
        )}
        {canShare && (
          <button
            onClick={() => onShare?.(deliverable)}
            className="flex items-center gap-1 text-[10px] text-accent hover:underline"
          >
            <Share2 className="w-3 h-3" />
            Share
          </button>
        )}
        {canRevoke && (
          <button
            onClick={() => onRevoke?.(deliverable)}
            className="flex items-center gap-1 text-[10px] text-destructive hover:underline"
          >
            <RotateCcw className="w-3 h-3" />
            Revoke
          </button>
        )}
      </div>
    </div>
  );
}